# ==============================================================================# 090_ENTITY_RESOLUTION_ENGINE.py## IOTEC ENTITY RESOLUTION ENGINE## Missão:# Resolver a identidade única das empresas.## ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonimport uuidfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class EntityResolutionEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_master_company(            id INTEGER PRIMARY KEY AUTOINCREMENT,            company_uuid TEXT UNIQUE,            canonical_name TEXT,            cnpj TEXT,            segment TEXT,            city TEXT,            state TEXT,            country TEXT,            created_at TEXT,            updated_at TEXT,            confidence REAL,            source_count INTEGER,            status TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ----------------------------------------------------------------------    def _sha(self, obj):        raw = json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ----------------------------------------------------------------------    def _find_existing(self, company):        if company["document"]:            row = self.conn.execute("""                SELECT *                FROM commercial_master_company                WHERE cnpj=?                LIMIT 1            """,(company["document"],)).fetchone()            if row:                return row        row=self.conn.execute("""            SELECT *            FROM commercial_master_company            WHERE                UPPER(canonical_name)=UPPER(?)                AND UPPER(city)=UPPER(?)                AND UPPER(state)=UPPER(?)            LIMIT 1        """,(            company["company_name"],            company["city"],            company["state"]        )).fetchone()        return row    # ----------------------------------------------------------------------    def process_latest(self):        registros=self.conn.execute("""            SELECT *            FROM commercial_normalized_company            ORDER BY id        """).fetchall()        novos=0        existentes=0        for row in registros:            company=dict(row)            existente=self._find_existing(company)            if existente:                self.conn.execute("""                    UPDATE commercial_master_company                    SET                        updated_at=?,                        source_count=source_count+1                    WHERE company_uuid=?                """,(                    datetime.utcnow().isoformat(),                    existente["company_uuid"]                ))                existentes+=1                continue            master={                "company_uuid":str(uuid.uuid4()),                "canonical_name":company["company_name"],                "cnpj":company["document"],                "segment":company["segment"],                "city":company["city"],                "state":company["state"],                "country":company["country"],                "created_at":datetime.utcnow().isoformat(),                "updated_at":datetime.utcnow().isoformat(),                "confidence":company["confidence"],                "source_count":1,                "status":"ACTIVE",                "metadata":{                    "origin":"090_ENTITY_RESOLUTION_ENGINE",                    "provider":company["provider"]                }            }            assinatura=self._sha(master)            self.conn.execute("""                INSERT INTO commercial_master_company(                    company_uuid,                    canonical_name,                    cnpj,                    segment,                    city,                    state,                    country,                    created_at,                    updated_at,                    confidence,                    source_count,                    status,                    metadata,                    hash                )                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)            """,(                master["company_uuid"],                master["canonical_name"],                master["cnpj"],                master["segment"],                master["city"],                master["state"],                master["country"],                master["created_at"],                master["updated_at"],                master["confidence"],                master["source_count"],                master["status"],                json.dumps(master["metadata"],ensure_ascii=False),                assinatura            ))            novos+=1        self.conn.commit()        return {            "processed":len(registros),            "new_companies":novos,            "existing_companies":existentes        }# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    engine=EntityResolutionEngine()    resultado=engine.process_latest()    print("="*80)    print("ENTITY RESOLUTION")    print("="*80)    for k,v in resultado.items():        print(f"{k:25}: {v}")    print("="*80)